"""Golden pages: three benchmark pages (generated by bench/templates.py, committed with their exact ground truth)
must not score below the thresholds in tests/golden/thresholds.json.  Needs tesseract + a headless browser."""
import json
import os

import cv2
import pytest

pytest.importorskip("rapidfuzz")

HERE = os.path.dirname(os.path.abspath(__file__))
GOLDEN = os.path.join(HERE, "golden")
THRESH = os.path.join(GOLDEN, "thresholds.json")
IDS = ["login-fa-light-0", "pricing-en-dark-0", "settings-fa-light-0"]


@pytest.mark.browser
@pytest.mark.ocr
@pytest.mark.parametrize("pid", IDS)
def test_golden_page_does_not_regress(pid, tmp_path):
    if not os.path.exists(THRESH):
        pytest.skip("no thresholds.json")
    from bench import run as R
    from bench.adapters import Mv2codeAdapter
    from bench.render import Browser
    th = json.load(open(THRESH, encoding="utf-8"))[pid]
    shot = cv2.cvtColor(cv2.imread(os.path.join(GOLDEN, pid + ".png")), cv2.COLOR_BGR2RGB)
    gt = R.prep_gt(json.load(open(os.path.join(GOLDEN, pid + ".json"), encoding="utf-8")))
    ad = Mv2codeAdapter("responsive", refine="off")
    with Browser() as br:
        res = R._convert_and_render(br, ad, pid, shot, str(tmp_path), True)
    r = R._score(res, shot, gt)
    r["_meta"] = gt["meta"]
    agg = R.aggregate({pid: r})
    got = {
        "ssim": agg["visual"]["ssim"],
        "editable": agg["editable"],
        "responsive_ok": agg["responsive_ok"],
        "macro_f1": agg["structure_macro_f1_spec"],
        "text_present": agg["text_all"]["present"],
        "text_cer": agg["text_all"]["cer"],
    }
    assert r["error"] is None
    for key in ("ssim", "editable", "responsive_ok", "macro_f1", "text_present"):
        assert got[key] >= th[key], f"{pid}: {key} {got[key]:.3f} < threshold {th[key]:.3f}"
    assert got["text_cer"] <= th["text_cer"], f"{pid}: CER {got['text_cer']:.3f} > threshold {th['text_cer']:.3f}"
